<script lang="ts">
  import { team } from '../stores/team.svelte.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import {
    TYPE_ICON_URLS,
    buildSynergyCards,
    buildSynergyRegionTabs,
    defaultSynergyRegionTab,
    regionLabel,
    type SynergyCardView,
  } from '../lib/synergyListLogic.js';
  import { showGameTooltip, hideGameTooltip, touchTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import { getPokemonSpriteUrl } from '../lib/cardSprites.ts';

  let selectedRegion = $state(
    defaultSynergyRegionTab(game as GameRuntime | null),
  );

  let regionTabs = $derived.by(() => {
    const gm = game as GameRuntime | null;
    if (!gm) return [];
    void gm.language;
    return buildSynergyRegionTabs(gm, team.playerTeam);
  });

  let cards = $derived.by((): SynergyCardView[] => {
    const gm = game as GameRuntime | null;
    if (!gm) return [];
    void gm.language;
    void selectedRegion;
    return buildSynergyCards(gm, team.playerTeam, { regionId: selectedRegion });
  });

  function cardHandlers(card: SynergyCardView) {
    return touchTooltipHandlers(() => ({
      title: card.tooltipTitle,
      body: card.tooltipDesc,
    }));
  }

  function activeLabel(): string {
    const gm = game as GameRuntime | null;
    return gm?.t?.('state.active') ?? 'Actif';
  }

  function pokemonLabel(): string {
    const gm = game as GameRuntime | null;
    return gm?.t?.('state.pokemon') ?? 'Pokémon';
  }

  function synergyOrLabel(): string {
    const gm = game as GameRuntime | null;
    const key = 'modal.synergyOr';
    const got = gm?.t?.(key);
    return got && got !== key ? got : 'OU';
  }

  function synergyAndLabel(): string {
    const gm = game as GameRuntime | null;
    const key = 'modal.synergyAnd';
    const got = gm?.t?.(key);
    return got && got !== key ? got : 'ET';
  }

  function speciesIsMatched(card: SynergyCardView, speciesName: string): boolean {
    return card.speciesProgress?.matchedSpecies.includes(speciesName) ?? false;
  }

  function lockedTabTooltip(regionId: string): string {
    const gm = game as GameRuntime | null;
    const name = regionLabel(gm, regionId);
    const key = 'tooltip.synergyRegionLocked';
    const tpl = gm?.t?.(key);
    if (tpl && tpl !== key) return tpl.replace('{region}', name);
    return `Visit ${name} to unlock these synergies`;
  }

  function selectRegion(regionId: string, locked: boolean, e: MouseEvent) {
    if (locked) {
      const gm = game as GameRuntime | null;
      if (gm?.scheduleTooltip) {
        gm.scheduleTooltip(e, '', lockedTabTooltip(regionId));
      }
      return;
    }
    selectedRegion = regionId;
  }
</script>

<div class="synergy-region-tabs" role="tablist">
  {#each regionTabs as tab (tab.regionId)}
    <button
      type="button"
      class="synergy-region-tab"
      class:synergy-region-tab--active={selectedRegion === tab.regionId}
      class:synergy-region-tab--locked={tab.locked}
      role="tab"
      aria-selected={selectedRegion === tab.regionId}
      onclick={(e) => selectRegion(tab.regionId, tab.locked, e)}
      onmouseenter={(e) => {
        if (tab.locked) showGameTooltip(e, '', lockedTabTooltip(tab.regionId));
      }}
      onmouseleave={hideGameTooltip}
    >
      {tab.label}
      {#if !tab.locked && tab.activeCount > 0}
        <span class="synergy-region-tab-badge">{tab.activeCount}</span>
      {/if}
    </button>
  {/each}
</div>

<div id="synergyListContent" class="synergy-list-grid">
  {#each cards as card (card.id)}
    {@const handlers = cardHandlers(card)}
    <div
      class="synergy-list-card"
      class:active={card.isActive}
      class:region-locked={card.isRegionLocked}
      role="button"
      tabindex="0"
      onmouseenter={handlers.onmouseenter}
      onmouseleave={handlers.onmouseleave}
      onfocus={handlers.onfocus}
      onblur={handlers.onblur}
      onclick={handlers.onclick}
      onkeydown={handlers.onkeydown}
    >
      <div class="synergy-list-types">
        {#each card.types as t (t)}
          <span class="synergy-type-badge" title={t}>
            {#if TYPE_ICON_URLS[t]}
              <img src={TYPE_ICON_URLS[t]} class="type-icon-img" alt={t} />
            {/if}
          </span>
        {/each}
      </div>
      <div class="synergy-list-info">
        <div class="synergy-list-title">
          <span>{card.name}</span>
          {#if card.isActive}
            <span class="synergy-list-active-badge">{activeLabel()}</span>
          {/if}
        </div>
        <div class="synergy-list-desc">{card.shortDesc}</div>
        <div class="synergy-progress">
          {#if card.speciesProgress}
            <span class="synergy-species-requirement">{card.speciesProgress.requirementLabel}</span>
            <span
              class="synergy-species-count"
              class:synergy-progress--met={card.speciesProgress.current >= card.speciesProgress.required}
              class:synergy-progress--unmet={card.speciesProgress.current < card.speciesProgress.required}
            >
              {card.speciesProgress.current}/{card.speciesProgress.required}
            </span>
            <span class="synergy-species-sprites">
              {#each card.speciesProgress.species as sp, i (sp)}
                {#if i > 0}
                  <span class="synergy-species-sep">
                    {card.speciesProgress.pickMode === 'any' ? synergyOrLabel() : synergyAndLabel()}
                  </span>
                {/if}
                <img
                  src={getPokemonSpriteUrl(sp, false)}
                  alt={sp}
                  class="synergy-species-sprite"
                  class:synergy-species-sprite--matched={speciesIsMatched(card, sp)}
                  title={sp}
                />
              {/each}
            </span>
          {/if}
          {#if card.allRequired && card.progressParts}
            {#each card.progressParts as part, i (part.type)}
              {#if i > 0}
                <span class="synergy-progress-sep">+</span>
              {/if}
              <span
                class="synergy-progress-part"
                class:synergy-progress--met={part.current >= part.required}
                class:synergy-progress--unmet={part.current < part.required}
              >
                {#if TYPE_ICON_URLS[part.type]}
                  <img src={TYPE_ICON_URLS[part.type]} class="type-icon-img" alt="" />
                {/if}
                {part.current}/{part.required}
              </span>
            {/each}
          {:else if card.simpleProgress}
            <span>{card.simpleProgress.current} / {card.simpleProgress.required} {pokemonLabel()}</span>
          {/if}
        </div>
        <div class="synergy-progress-bar">
          <div class="synergy-progress-fill" style="width: {card.progressPercent}%;"></div>
        </div>
      </div>
    </div>
  {/each}
</div>
